## Narrowing — estreitando o tipo

```typescript
function processar(valor: string | number) {
  // typeof estreita
  if (typeof valor === "string") {
    return valor.toUpperCase(); // valor é string aqui
  }
  return valor.toFixed(2);       // valor é number aqui
}
```

