## HTTP puro vs Express

```typescript
// http nativo — verboso
import http from "http";

const server = http.createServer((req, res) => {
  if (req.method === "GET" && req.url === "/usuarios") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify([{ nome: "Ana" }]));
  }
});

server.listen(3000);
